<template>
  <div class="report-page">
    <div class="toolbar">
      <div class="filters">
        <el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" :clearable="false" />
        <el-select v-model="status" clearable placeholder="全部状态" class="status-filter"><el-option v-for="item in statuses" :key="item.value" :label="item.label" :value="item.value" /></el-select>
        <el-button type="primary" :icon="Refresh" :loading="loading" @click="load">刷新</el-button>
      </div>
      <span class="hint">每班直播结束后上报累计值，系统自动计算本班差额</span>
    </div>
    <div class="summary"><div v-for="item in summary" :key="item.value" :class="['summary-item', item.tone]"><b>{{ counts[item.value] || 0 }}</b><span>{{ item.label }}</span></div></div>
    <el-table v-loading="loading" :data="rows" height="calc(100vh - 235px)" stripe>
      <el-table-column label="直播场次" min-width="190"><template #default="{ row }"><div class="session"><strong>{{ row.roomName || row.reportedRoomName }}</strong><span>{{ row.liveStartTime }}</span></div></template></el-table-column>
      <el-table-column label="班次" min-width="170"><template #default="{ row }">{{ row.anchorName || '待匹配' }}<small v-if="row.startTime">{{ row.startTime.slice(11, 16) }} - {{ row.endTime?.slice(11, 16) }}</small></template></el-table-column>
      <el-table-column label="累计数据" min-width="255"><template #default="{ row }"><div class="metrics"><span>曝光 {{ row.exposureTotal }}</span><span>观看 {{ row.watchTotal }}</span><span>互动 {{ row.interactionTotal }}</span><span>粉丝 {{ row.newFanTotal }}</span><span>成交 {{ row.dealTotal }}</span></div></template></el-table-column>
      <el-table-column label="本班差额" min-width="255"><template #default="{ row }"><div class="metrics delta"><span>曝光 {{ row.exposureDelta ?? '-' }}</span><span>观看 {{ row.watchDelta ?? '-' }}</span><span>互动 {{ row.interactionDelta ?? '-' }}</span><span>粉丝 {{ row.newFanDelta ?? '-' }}</span><span>成交 {{ row.dealDelta ?? '-' }}</span></div></template></el-table-column>
      <el-table-column label="转化指标" min-width="285"><template #default="{ row }"><div class="rate-metrics"><span><small>曝光进入率</small><b>{{ metricRate(row.watchDelta, row.exposureDelta) }}</b></span><span><small>观看成交率</small><b>{{ metricRate(row.dealDelta, row.watchDelta) }}</b></span><span><small>转粉率</small><b>{{ metricRate(row.newFanDelta, row.watchDelta) }}</b></span><span><small>互动率</small><b>{{ metricRate(row.interactionDelta, row.watchDelta) }}</b></span></div></template></el-table-column>
      <el-table-column label="状态" width="150"><template #default="{ row }"><div class="row-status"><el-tag :type="tagType(row.matchStatus)">{{ statusLabel(row.matchStatus) }}</el-tag><el-tooltip v-if="row.dingNotifyError" :content="row.dingNotifyError" placement="top"><small :class="['notify-state', notifyState(row).tone]">{{ notifyState(row).label }}</small></el-tooltip><small v-else :class="['notify-state', notifyState(row).tone]">{{ notifyState(row).label }}</small></div></template></el-table-column>
      <el-table-column label="操作" width="230" fixed="right"><template #default="{ row }"><el-button v-if="row.matchStatus === 'PENDING_ROOM'" link type="primary" @click="openBind(row)">认领直播间</el-button><el-button v-if="row.roomId" link type="primary" @click="openRematch(row)">{{ row.shiftId ? '调整班次' : '匹配班次' }}</el-button><el-button v-if="row.roomId" link type="primary" @click="openSupplement(row)">补录漏报</el-button><el-button v-if="row.matchStatus === 'ANOMALY'" link type="danger" @click="recalculate(row)">重新计算</el-button></template></el-table-column>
    </el-table>
    <el-drawer v-model="drawer.visible" :title="drawer.type === 'bind' ? '认领直播间' : '调整记录班次'" size="420px">
      <el-form label-position="top"><el-form-item v-if="drawer.type === 'bind'" label="系统直播间" required><el-select v-model="drawer.roomId" filterable placeholder="选择直播间" style="width:100%"><el-option v-for="room in rooms" :key="room.roomId" :label="room.roomName" :value="room.roomId" /></el-select></el-form-item><el-form-item v-else label="分配给班次" required><el-select v-model="drawer.shiftId" :loading="candidateLoading" filterable placeholder="选择本场直播的班次" style="width:100%"><el-option v-for="shift in candidateShifts" :key="shift.shiftId" :label="`${shift.anchorName} · ${shift.startTime} - ${shift.endTime}`" :value="shift.shiftId" /></el-select></el-form-item><el-form-item label="处理说明" required><el-input v-model.trim="drawer.reason" type="textarea" :rows="3" maxlength="500" placeholder="请说明认领或调整原因" /></el-form-item></el-form>
      <template #footer><el-button @click="drawer.visible = false">取消</el-button><el-button type="primary" :loading="saving" @click="submitDrawer">保存</el-button></template>
    </el-drawer>
    <el-drawer v-model="supplement.visible" title="补录漏报累计值" size="460px">
      <el-form label-position="top"><el-form-item label="漏报班次" required><el-select v-model="supplement.shiftId" :loading="candidateLoading" filterable placeholder="选择本场直播的班次" style="width:100%"><el-option v-for="shift in candidateShifts" :key="shift.shiftId" :label="`${shift.anchorName} · ${shift.startTime} - ${shift.endTime}`" :value="shift.shiftId" /></el-select></el-form-item><el-form-item label="数据时点" required><el-date-picker v-model="supplement.snapshotAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%" /></el-form-item><div class="metric-form"><el-form-item v-for="item in metricFields" :key="item.key" :label="`${item.label}累计值`" required><el-input-number v-model="supplement[item.key]" :min="0" :max="999999999" controls-position="right" /></el-form-item></div><el-form-item label="补录原因" required><el-input v-model.trim="supplement.reason" type="textarea" :rows="3" maxlength="500" /></el-form-item></el-form>
      <template #footer><el-button @click="supplement.visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitSupplement">保存并重算</el-button></template>
    </el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import { bindMetricReportingRoom, getMetricOptions, listMetricReporting, listMetricReportingShifts, recalculateMetricReporting, rematchMetricReporting, supplementMetricReporting } from '@/api/liveMetrics'
const today = new Date(); const fmt = value => { const d = new Date(value); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` }
const dateRange = ref([fmt(new Date(today.getTime() - 86400000 * 2)), fmt(today)]); const status = ref(''); const rows = ref([]); const rooms = ref([]); const candidateShifts = ref([]); const candidateLoading = ref(false); const loading = ref(false); const saving = ref(false)
const statuses = [{ label: '待认领直播间', value: 'PENDING_ROOM' }, { label: '待匹配班次', value: 'PENDING_SHIFT' }, { label: '疑似漏报', value: 'SUSPECT_MISSING' }, { label: '数据异常', value: 'ANOMALY' }, { label: '已匹配', value: 'MATCHED' }]
const summary = statuses; const counts = computed(() => statuses.reduce((result, item) => { result[item.value] = rows.value.filter(row => row.matchStatus === item.value).length; return result }, {})); const drawer = reactive({ visible: false, type: 'bind', row: null, roomId: null, shiftId: null, reason: '' })
const metricFields = [{ key: 'exposureTotal', label: '曝光' }, { key: 'watchTotal', label: '观看' }, { key: 'interactionTotal', label: '互动' }, { key: 'newFanTotal', label: '粉丝' }, { key: 'dealTotal', label: '成交' }]
const supplement = reactive({ visible: false, sessionId: null, roomId: null, shiftId: null, snapshotAt: '', exposureTotal: 0, watchTotal: 0, interactionTotal: 0, newFanTotal: 0, dealTotal: 0, reason: '' })
const statusLabel = value => statuses.find(item => item.value === value)?.label || value || '待处理'; const tagType = value => value === 'MATCHED' ? 'success' : value === 'ANOMALY' ? 'danger' : value === 'SUSPECT_MISSING' ? 'warning' : 'info'
const metricRate = (numerator, denominator) => { if (numerator === null || numerator === undefined || denominator === null || denominator === undefined) return '-'; const top = Number(numerator); const base = Number(denominator); return Number.isFinite(top) && Number.isFinite(base) && top >= 0 && base > 0 ? `${(top * 100 / base).toFixed(2)}%` : '-' }
const notifyState = row => { if (row.matchStatus !== 'MATCHED') return { label: '匹配后通知', tone: 'muted' }; if (!row.dingUserId) return { label: '未绑定钉钉', tone: 'warning' }; if (row.dingNotifyStatus === 'SENT') return { label: '钉钉已通知', tone: 'success' }; if (row.dingNotifyStatus === 'FAILED') return { label: '钉钉通知失败', tone: 'danger' }; return { label: '钉钉通知处理中', tone: 'muted' } }
async function load () { loading.value = true; try { const [report, options] = await Promise.all([listMetricReporting({ beginDate: dateRange.value[0], endDate: dateRange.value[1], matchStatus: status.value }), getMetricOptions()]); rows.value = report.data || []; rooms.value = options.data?.allRooms || [] } finally { loading.value = false } }
function openBind (row) { Object.assign(drawer, { visible: true, type: 'bind', row, roomId: null, shiftId: null, reason: '' }) }
async function loadCandidateShifts (sessionId) { candidateShifts.value = []; candidateLoading.value = true; try { const response = await listMetricReportingShifts(sessionId); candidateShifts.value = response.data || [] } finally { candidateLoading.value = false } }
function openRematch (row) { Object.assign(drawer, { visible: true, type: 'rematch', row, roomId: row.roomId || null, shiftId: row.shiftId || null, reason: '' }); loadCandidateShifts(row.sessionId) }
async function submitDrawer () { if (drawer.type === 'bind' && !drawer.roomId) return ElMessage.warning('请选择系统直播间'); if (drawer.type !== 'bind' && !drawer.shiftId) return ElMessage.warning('请选择对应班次'); if (!drawer.reason) return ElMessage.warning('请填写处理说明'); saving.value = true; try { if (drawer.type === 'bind') await bindMetricReportingRoom({ sessionId: drawer.row.sessionId, roomId: drawer.roomId, reason: drawer.reason }); else await rematchMetricReporting({ submissionId: drawer.row.submissionId, shiftId: drawer.shiftId, reason: drawer.reason }); ElMessage.success(drawer.type === 'bind' ? '直播间已认领' : '班次已调整，整场差额已重新计算'); drawer.visible = false; await load() } finally { saving.value = false } }
function openSupplement (row) { Object.assign(supplement, { visible: true, sessionId: row.sessionId, roomId: row.roomId, shiftId: null, snapshotAt: row.snapshotAt || '', exposureTotal: Number(row.exposureTotal || 0), watchTotal: Number(row.watchTotal || 0), interactionTotal: Number(row.interactionTotal || 0), newFanTotal: Number(row.newFanTotal || 0), dealTotal: Number(row.dealTotal || 0), reason: '' }); loadCandidateShifts(row.sessionId) }
async function submitSupplement () { if (!supplement.shiftId || !supplement.snapshotAt || !supplement.reason) return ElMessage.warning('请补全班次、数据时点和补录原因'); saving.value = true; try { await supplementMetricReporting({ ...supplement, visible: undefined, roomId: undefined }); ElMessage.success('漏报已补录，后续班次差额已重新计算'); supplement.visible = false; await load() } finally { saving.value = false } }
async function recalculate (row) { await recalculateMetricReporting(row.sessionId); ElMessage.success('已重新计算'); await load() }
onMounted(load)
</script>

<style scoped>
.report-page{padding:16px;background:#f5f7fa;min-height:calc(100vh - 84px)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px;background:#fff;border:1px solid #e6e9ee}.filters{display:flex;gap:8px}.status-filter{width:150px}.hint{color:#98a2b3;font-size:12px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:10px 0}.summary-item{display:flex;align-items:baseline;gap:8px;padding:12px;background:#fff;border-left:3px solid #aeb8c5}.summary-item b{font-size:20px}.summary-item span{color:#667085;font-size:12px}.summary-item:nth-child(1){border-color:#e6a23c}.summary-item:nth-child(3){border-color:#f56c2d}.summary-item:nth-child(4){border-color:#d64545}.summary-item:nth-child(5){border-color:#23a26d}.session{display:grid;gap:3px}.session span,small{display:block;color:#98a2b3;font-size:11px}.metrics{display:flex;gap:5px;flex-wrap:wrap}.metrics span{padding:3px 5px;background:#f5f7f9;color:#667085;font-size:11px}.metrics.delta span{background:#fff4ed;color:#d85d1d}.rate-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px 12px}.rate-metrics span{display:flex;align-items:center;justify-content:space-between;gap:8px;white-space:nowrap}.rate-metrics small{color:#7b8491}.rate-metrics b{color:#d85d1d;font-size:12px}.row-status{display:grid;justify-items:start;gap:5px}.notify-state{font-size:10px}.notify-state.success{color:#239568}.notify-state.danger{color:#d64545}.notify-state.warning{color:#c47a18}.notify-state.muted{color:#98a2b3}.metric-form{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}.metric-form :deep(.el-input-number){width:100%}@media(max-width:760px){.report-page{padding:8px}.toolbar{align-items:stretch;flex-direction:column}.filters{display:grid;grid-template-columns:1fr 1fr}.filters :deep(.el-date-editor){width:100%}.filters .el-button{grid-column:1/-1}.hint{display:none}.summary{grid-template-columns:repeat(2,1fr)}}
</style>
